// Confirms the incoming item is a well-formed Report Contract
// (docs/contracts/report-contract.md) before any draft logic runs. This
// is the only node that validates the contract's envelope shape - 'Build
// Jira Draft Contract' trusts it completely.
const STAGE = 'jira_agent';
const WORKFLOW_VERSION = '1.0';
const VALID_STATUSES = ['PASS', 'FAIL', 'BLOCKED', 'MANUAL_REVIEW'];

function errorPayload(code, message, details) {
  return {
    status: 'ERROR',
    stage: STAGE,
    code,
    message,
    details: details || {},
    timestamp: new Date().toISOString(),
    workflow_version: WORKFLOW_VERSION
  };
}

const item = $input.item.json;

// ERROR payloads produced upstream (Documentation Agent, Excel Writer,
// or anything earlier) are not Report Contracts and must not be
// re-validated as one - pass them through unchanged, same convention as
// every prior workflow.
if (item && item.status === 'ERROR') {
  return { json: item };
}

if (typeof item !== 'object' || item === null || Array.isArray(item)) {
  return { json: errorPayload(
    'INVALID_REPORT_CONTRACT',
    'Report Contract must be a JSON object',
    { received_type: Array.isArray(item) ? 'array' : typeof item }
  ) };
}

const requiredFields = ['workflow_version', 'report_version', 'test_case', 'decision', 'report'];
const missingFields = requiredFields.filter((field) => item[field] === undefined);

if (missingFields.length > 0) {
  return { json: errorPayload(
    'INVALID_REPORT_CONTRACT',
    `Report Contract is missing required field(s): ${missingFields.join(', ')}`,
    { missing_fields: missingFields }
  ) };
}

const tc = item.test_case;
if (typeof tc !== 'object' || tc === null || Array.isArray(tc) ||
    typeof tc.test_id !== 'string' || tc.test_id.trim() === '' ||
    typeof tc.description !== 'string' ||
    typeof tc.expected_result !== 'string' ||
    typeof tc.steps !== 'string' ||
    typeof tc.verification_type !== 'string') {
  return { json: errorPayload(
    'INVALID_REPORT_CONTRACT',
    'Report Contract test_case must be an object with test_id/description/expected_result/steps/verification_type',
    {}
  ) };
}

const r = item.report;
if (typeof r !== 'object' || r === null || Array.isArray(r) ||
    !VALID_STATUSES.includes(r.status) ||
    typeof r.actual_result !== 'string' ||
    typeof r.reasoning !== 'string' ||
    typeof r.manual_review !== 'boolean') {
  return { json: errorPayload(
    'INVALID_REPORT_CONTRACT',
    'Report Contract report object is missing or has an invalid status/actual_result/reasoning/manual_review',
    { test_id: tc.test_id }
  ) };
}

const v = item.decision && item.decision.verdict;
if (typeof v !== 'object' || v === null || Array.isArray(v) ||
    !Array.isArray(v.evidence) || v.evidence.length === 0 ||
    typeof v.next_action !== 'string') {
  return { json: errorPayload(
    'INVALID_REPORT_CONTRACT',
    'Report Contract decision.verdict must be an object with a non-empty evidence array and a next_action',
    { test_id: tc.test_id }
  ) };
}

return { json: item };

// Build Jira Draft Contract - the Jira Agent's only real work. Every
// jira.* value is either reused verbatim from the Report Contract or
// built through a fixed, deterministic template/lookup table - no AI
// call, no free-form generation. See docs/contracts/jira-draft-
// contract.md and the Design Note sticky.
const JIRA_WORKFLOW_VERSION = '1.0';
const JIRA_CONTRACT_VERSION = '1.0';

// The single config point Task 6's brief calls for ('MANUAL_REVIEW
// optional, configurable'). Off by default - MANUAL_REVIEW cases are
// held for a human to read in the report, not auto-drafted, until this
// is deliberately turned on.
const DRAFT_ON_MANUAL_REVIEW = false;

// verification_type -> Jira component(s). Single source of truth, same
// manual-sync convention as AGENT_ROUTES (01-ingestion.json) / COLUMN_MAP
// (06.1-excel-writer.json) - Milestone 1 only ever produces 'api'.
const COMPONENT_MAP = {
  api: ['API']
};

function buildLabels(status) {
  const labels = ['ai-detected'];
  if (status === 'FAIL') labels.push('needs-triage');
  if (status === 'MANUAL_REVIEW') labels.push('manual-review');
  return labels;
}

// Reuses the routing decision 05-decision-orchestrator.json's Apply
// Trust Rules already made (TRUST_CONFIG.FAIL_AUTO_JIRA_THRESHOLD) -
// never re-derives a confidence threshold here. 'create_jira' only ever
// occurs on a high-confidence FAIL; 'flag_for_review' covers every
// lower-confidence FAIL and every MANUAL_REVIEW.
function priorityFromNextAction(nextAction) {
  if (nextAction === 'create_jira') return 'High';
  if (nextAction === 'flag_for_review') return 'Medium';
  return null;
}

const item = $input.item.json;
const report = item.report;
const testCase = item.test_case;
const verdict = item.decision.verdict;

const required = report.status === 'FAIL' || (report.status === 'MANUAL_REVIEW' && DRAFT_ON_MANUAL_REVIEW);

const jira = required ? {
  required: true,
  summary: `${report.status}: ${testCase.description}`,
  description: report.reasoning,
  expected_result: testCase.expected_result,
  actual_result: report.actual_result,
  reproduction_steps: testCase.steps,
  evidence: verdict.evidence,
  priority: priorityFromNextAction(verdict.next_action),
  labels: buildLabels(report.status),
  components: COMPONENT_MAP[testCase.verification_type] || [],
  manual_review: report.manual_review
} : {
  required: false,
  summary: null,
  description: null,
  expected_result: null,
  actual_result: null,
  reproduction_steps: null,
  evidence: [],
  priority: null,
  labels: [],
  components: [],
  manual_review: report.manual_review
};

return { json: {
  workflow_version: JIRA_WORKFLOW_VERSION,
  jira_version: JIRA_CONTRACT_VERSION,
  report: item,
  jira
} };
